document.addEventListener('input',e=>{if(e.target.name==='amount'&&e.target.closest('#payment-form')){const full=e.target.closest('#payment-form').querySelector('#pay-full-debt');if(full?.checked)full.checked=false}});
document.addEventListener('submit',async e=>{
 if(e.target.id==='password-form'){
   e.preventDefault();const form=e.target,error=document.getElementById('password-form-error'),currentPassword=form.elements.currentPassword.value,newPassword=form.elements.newPassword.value,confirmPassword=form.elements.confirmPassword.value,user=auth.currentUser;
   error.hidden=true;error.textContent='';
   const showError=message=>{error.textContent=message;error.hidden=false};
   if(!currentPassword||!newPassword||!confirmPassword){showError('Completa todos los campos.');return}
   if(newPassword!==confirmPassword){showError('Las contraseñas nuevas no coinciden.');return}
   if(newPassword.length<6){showError('La nueva contraseña debe tener al menos 6 caracteres.');return}
   if(newPassword===currentPassword){showError('La nueva contraseña debe ser distinta a la contraseña actual.');return}
   if(!user||user.uid!==sessionUser?.uid||!user.email){showError('No se pudo verificar tu sesión. Vuelve a iniciar sesión.');return}
   const button=form.querySelector('[type="submit"]');button.disabled=true;button.textContent='Actualizando…';
   try{const credential=EmailAuthProvider.credential(user.email,currentPassword);await reauthenticateWithCredential(user,credential);await updatePassword(user,newPassword);form.reset();closeModal();toast('Contraseña actualizada correctamente.')}
   catch(err){showError(passwordErrorMessage(err.code));form.elements.currentPassword.value='';form.elements.currentPassword.focus()}
   finally{if(form.isConnected){button.disabled=false;button.textContent='Cambiar contraseña'}}
   return;
 }
 if(e.target.id==='login-form'){
   e.preventDefault();const form=e.target,fd=new FormData(form),username=String(fd.get('user')||'').trim().toLowerCase(),password=String(fd.get('password')||''),email=usernameEmails[username],error=document.getElementById('login-error');error.hidden=true;
   if(!email){showLoginError('Escribe uno de los usuarios habilitados: gerson, maribel, josue o benjamin.');return}
   const button=form.querySelector('[type="submit"]');button.disabled=true;button.textContent='Ingresando…';
   try{await setPersistence(auth,browserLocalPersistence);await signInWithEmailAndPassword(auth,email,password);form.elements.password.value=''}catch(err){console.error(err);showLoginError(err.code==='auth/invalid-credential'||err.code==='auth/user-not-found'||err.code==='auth/wrong-password'?'El usuario o la contraseña no son correctos.':'No se pudo iniciar sesión. Revisa tu conexión e inténtalo de nuevo.')}finally{button.disabled=false;button.textContent='Ingresar'}
   return;
 }
 if(e.target.id==='prior-debt-form'){
   e.preventDefault();if(role!=='admin'){toast('Solo administración puede registrar deudas.',true);return}
   const fd=new FormData(e.target),debtorId=fd.get('debtorId'),creditorId=fd.get('creditorId'),amount=roundCurrency(Number(fd.get('amount')));
   if(debtorId===creditorId||amount<=0){toast('Selecciona personas distintas y un monto mayor que cero.',true);return}
   const previous=structuredClone(store.priorDebts),debt={id:crypto.randomUUID(),debtorId,creditorId,amount,date:fd.get('date'),reason:String(fd.get('reason')||'').trim(),notes:String(fd.get('notes')||'').trim(),createdAt:new Date().toISOString()};store.priorDebts.push(debt);
   try{await savePriorDebtToCloud(debt);closeModal();toast('Deuda anterior registrada.')}catch(error){store.priorDebts=previous;handleWriteError(error)}return;
 }
 if(e.target.id==='expense-form'){
   e.preventDefault();if(role!=='admin'){toast('Solo administración puede registrar o editar gastos.',true);return}
   const form=e.target,fd=new FormData(form),editId=form.dataset.editId,previous=editId?store.expenses.find(item=>item.id===editId):null,amount=Number(fd.get('amount')),participants=fd.getAll('participants');
   if(editId&&!previous){toast('No se encontró el gasto que intentas editar.',true);return}
   if(!participants.length){toast('Selecciona al menos un participante.',true);return}
   const allocations={};
   if(fd.get('distribution')==='custom'){
     let sum=0;for(const id of participants){const value=Number(document.querySelector(`[data-custom-share="${id}"]`)?.value)||0;if(value<0){toast('Las participaciones no pueden ser negativas.',true);return}allocations[id]=value;sum+=value}
     if(Math.round(sum*100)!==Math.round(amount*100)){toast(`La distribución suma ${money(sum)} y debe ser ${money(amount)}.`,true);return}
   }
   const category=store.categories.find(item=>item.name===fd.get('category')),beneficiary=store.beneficiaries.find(item=>item.name===fd.get('beneficiary'));
   if(!fd.get('date')||!String(fd.get('description')||'').trim()||amount<=0||!category||!fd.get('expenseType')||!beneficiary||!fd.get('paidBy')){toast('Completa la fecha, monto, descripción, categoría, beneficiario, tipo y persona que adelantó.',true);return}
   if(!previous&&category.active===false){toast('Activa la categoría antes de registrar un gasto.',true);return}
   if(!previous&&beneficiary.active===false){toast('Activa el beneficiario antes de registrar un gasto.',true);return}
    const paidBy=fd.get('paidBy'),item={id:previous?.id||doc(collection(db,'gastos')).id,date:fd.get('date'),createdAt:previous?.createdAt||new Date().toISOString(),createdByUid:previous?.createdByUid||sessionUser.uid,createdByUsername:previous?.createdByUsername||profile.usuario,description:String(fd.get('description')).trim(),category:fd.get('category'),expenseType:fd.get('expenseType'),subcategory:fd.get('expenseType'),beneficiary:fd.get('beneficiary'),amount:roundCurrency(amount),paidBy,paidByUsername:person(paidBy).username,paidByUid:peopleUids[person(paidBy).username]||null,participants,participantUsernames:participants.map(id=>person(id).username),participantUids:Object.fromEntries(participants.map(id=>[person(id).username,peopleUids[person(id).username]||null])),distribution:fd.get('distribution'),receipt:fd.get('receipt'),notes:String(fd.get('notes')||'').trim(),active:true,status:'active'};
   if(item.distribution==='equal'){const cents=Math.round(item.amount*100),base=Math.floor(cents/participants.length),remainder=cents%participants.length;item.allocations=Object.fromEntries(participants.map((id,index)=>[id,(base+(index<remainder?1:0))/100]))}
   if(Object.keys(allocations).length)item.allocations=allocations;
    const historyText=previous?`Gerson editó el gasto “${item.description}”.`:`Gerson registró “${item.description}”.`,extraHistory=item.receipt&&item.receipt!==previous?.receipt?[['receipt',`Se agregó un comprobante a “${item.description}”.`]]:[];
    try{await saveCloudRecord('gastos',item,'expense',historyText,previous?.id,extraHistory);closeModal();toast(previous?'Gasto actualizado.':'El gasto se guardó correctamente.')}catch(error){handleWriteError(error)}return;
 }
 if(e.target.id==='payment-form'){
   e.preventDefault();if(role!=='admin'){toast('Solo administración puede registrar o editar pagos.',true);return}
    const form=e.target,fd=new FormData(form),editId=form.dataset.editId,previous=editId?store.payments.find(item=>item.id===editId):null,personId=fd.get('personId'),payeeId=fd.get('payeeId')||'gerson',paymentPerson=person(personId),item={id:previous?.id||doc(collection(db,'pagos')).id,personId,payerId:personId,payeeId,personUsername:paymentPerson.username,personUid:peopleUids[paymentPerson.username]||null,date:fd.get('date'),amount:roundCurrency(Number(fd.get('amount'))),method:fd.get('method'),concept:String(fd.get('note')||'').trim()||'Pago de deuda',note:String(fd.get('note')||'').trim(),receipt:fd.get('receipt'),createdAt:previous?.createdAt,createdByUid:previous?.createdByUid||sessionUser.uid,createdByUsername:previous?.createdByUsername||profile.usuario};
   if(editId&&!previous){toast('No se encontró el pago que intentas editar.',true);return}
   if(item.amount<=0){toast('Ingresa un monto mayor que cero.',true);return}
    if(item.personId===item.payeeId){toast('La persona que paga y quien recibe deben ser distintas.',true);return}
    const available=debtBetween(item.personId,item.payeeId,previous?.id||null);
    if(item.amount<=0||item.amount>available+.005){toast(`El pago debe ser mayor que cero y no superar la deuda de ${money(available)}.`,true);return}
    const debtAfter=Math.max(0,available-item.amount),debtBefore=Math.max(0,debtBetween(item.personId,item.payeeId,previous?.id||null));
    const historyText=previous?`Pago de ${paymentPerson.first} modificado por Gerson. Nuevo monto: ${money(item.amount)}; deuda actual: ${money(debtAfter)}.`:`${paymentPerson.first} realizó un pago de ${money(item.amount)}, registrado por Gerson. Deuda anterior: ${money(debtBefore)}; deuda actual: ${money(debtAfter)}.`,extraHistory=[...(item.receipt&&item.receipt!==previous?.receipt?[['receipt',`Se agregó el comprobante de un pago de ${paymentPerson.first}.`]]:[]),...(debtBefore>0&&debtAfter===0?[["payment",`${paymentPerson.first} completó su deuda.`]]:[])];
    try{await saveCloudRecord('pagos',item,'payment',historyText,previous?.id,extraHistory);closeModal();toast(previous?'Pago actualizado.':`Pago de ${money(item.amount)} registrado.`)}catch(error){handleWriteError(error)}return;
 }
});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if(e.key==='Tab'){const modal=document.querySelector('#modal-root .modal');if(!modal)return;const focusable=[...modal.querySelectorAll('a[href],button:not([disabled]),input:not([disabled]),select:not([disabled]),textarea:not([disabled])')];if(!focusable.length)return;if(e.shiftKey&&document.activeElement===focusable[0]){e.preventDefault();focusable.at(-1).focus()}else if(!e.shiftKey&&document.activeElement===focusable.at(-1)){e.preventDefault();focusable[0].focus()}}});
